<?php
require __DIR__.'/_common.php';
try{$in=body_json();$token=trim((string)($in['token']??''));if($token==='')respond(['error'=>'Missing token.'],400);$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("UPDATE orders SET status='DELIVERED',delivered_at=NOW() WHERE qr_token=? AND status='ACTIVE' RETURNING order_no,delivered_at");$s->execute([$token]);$o=$s->fetch();if($o){$pdo->commit();respond(['ok'=>true,'orderNo'=>$o['order_no'],'status'=>'DELIVERED','deliveredAt'=>$o['delivered_at']]);}$c=$pdo->prepare('SELECT order_no,status,delivered_at FROM orders WHERE qr_token=?');$c->execute([$token]);$x=$c->fetch();$pdo->rollBack();if(!$x)respond(['error'=>'Order not found / invalid QR.'],404);respond(['error'=>'This QR has already been used or the order is not active.','orderNo'=>$x['order_no'],'status'=>$x['status'],'deliveredAt'=>$x['delivered_at']],409);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e);respond(['error'=>'Unable to confirm delivery.'],500);}
